from sortedcontainers import SortedDict

class MyCalendar:
    def __init__(self):
        self.bookings = SortedDict()          # start time -> end time, kept sorted

    def book(self, start, end):
        idx = self.bookings.bisect_right(start)
        # check the booking just before (floor)
        if idx > 0:
            prev_start = self.bookings.keys()[idx - 1]
            if self.bookings[prev_start] > start:
                return False
        # check the booking just after (ceiling)
        if idx < len(self.bookings):
            next_start = self.bookings.keys()[idx]
            if next_start < end:
                return False
        self.bookings[start] = end
        return True

