import java.util.*;

public class MyCalendar {
    TreeMap<Integer, Integer> bookings = new TreeMap<>();   // start -> end, kept sorted

    boolean book(int start, int end) {
        Map.Entry<Integer, Integer> prev = bookings.floorEntry(start);
        if (prev != null && prev.getValue() > start) return false;      // floor neighbor overlaps
        Map.Entry<Integer, Integer> next = bookings.ceilingEntry(start);
        if (next != null && next.getKey() < end) return false;           // ceiling neighbor overlaps
        bookings.put(start, end);
        return true;
    }
}

