#include <bits/stdc++.h>
using namespace std;

class MyCalendar {
public:
    map<int,int> bookings;   // start -> end, kept sorted automatically

    bool book(int start, int end) {
        auto next = bookings.lower_bound(start);
        if (next != bookings.end() && next->first < end) return false;   // ceiling neighbor overlaps
        if (next != bookings.begin()) {
            auto prev = prev_iterator(next);
            if (prev->second > start) return false;                        // floor neighbor overlaps
        }
        bookings[start] = end;
        return true;
    }

private:
    map<int,int>::iterator prev_iterator(map<int,int>::iterator it) {
        return --it;
    }
};
